// Enhanced Prepare Email Prompt with Complete Data Access
const inputData = $input.first().json || {};
const caseFile = inputData.validatedUnifiedCaseFile || {};

// Access intake data with enhanced fallback logic
let intake = {};
let clientName = 'Client';
let attorneyName = 'Attorney';  
let caseReference = 'CASE-001';

if (caseFile && typeof caseFile === 'object') {
  // Primary: Try to get from processed intake data
  if (caseFile.intakeFormData && caseFile.intakeFormData.data) {
    intake = caseFile.intakeFormData.data;
    clientName = intake.clientInfo?.clientName || clientName;
    attorneyName = intake.attorneyInfo?.attorneyName || attorneyName;
    caseReference = intake.caseInfo?.caseReference || caseReference;
  }

  // Secondary: Try to get from caseInfo (fallback populated in merger)
  if (caseFile.caseInfo) {
    clientName = caseFile.caseInfo.clientName || clientName;
    attorneyName = caseFile.caseInfo.attorneyName || attorneyName;
    caseReference = caseFile.caseInfo.caseReference || caseReference;
  }

  // Tertiary: Check if fallback was used in processing details
  if (caseFile.intakeFormData?.processingDetails?.fallbackUsed && caseFile.intakeFormData?.processingDetails?.fallbackData) {
    const fallbackData = caseFile.intakeFormData.processingDetails.fallbackData;
    clientName = fallbackData.clientName || clientName;
    attorneyName = fallbackData.attorneyName || attorneyName;
    caseReference = fallbackData.caseReference || caseReference;
  }
}

// Build comprehensive case details with both branches
let caseDetails = `This case involves ${clientName}. Processing Results:\\n`;

// Intake processing status
if (caseFile.intakeFormData) {
  caseDetails += `- Intake form: ${caseFile.intakeFormData.status}`;
  if (caseFile.intakeFormData.status === "failed" && caseFile.intakeFormData.processingDetails?.fallbackUsed) {
    caseDetails += ` (using fallback data)`;
  }
  caseDetails += `\\n`;
}

// Case documents processing status  
if (caseFile.caseDocumentsAnalysis) {
  caseDetails += `- Case documents: ${caseFile.caseDocumentsAnalysis.status}\\n`;
}

// Add processing summary
if (caseFile.processingSummary) {
  caseDetails += `\\nProcessing Summary: ${caseFile.processingSummary.successfulBranches} of ${caseFile.processingSummary.totalBranchesProcessed} branches completed successfully.`;
}

// Enhanced prompt with better context
const emailPrompt = `Write a professional legal findings email using these EXACT values:\n\nCLIENT NAME: ${clientName}\nATTORNEY NAME: ${attorneyName}  \nCASE REFERENCE: ${caseReference}\n\nIMPORTANT: Use the actual names above, NOT template variables.\n\nCase Processing Information:\n${caseDetails}\n\nWrite a professional legal findings email that:\n1. Uses the EXACT names provided above\n2. Acknowledges the current processing status  \n3. Provides appropriate guidance based on available information\n4. Maintains professional tone regardless of processing completeness\n5. Indicates if additional documents may improve the analysis\n\nFormat:\nSubject: Legal Analysis Findings - ${caseReference}\n\nDear ${clientName},\n\nI have completed the initial analysis of your legal matter (Case Reference: ${caseReference}). \n\n[Professional content based on available data]\n\nPlease let me know if you have any questions or if additional documentation becomes available.\n\nSincerely,\n${attorneyName}\nBernhardt Riley Attorneys at Law`;

return [{
  json: {
    emailPrompt,
    clientName,
    attorneyName,
    caseReference,
    originalData: inputData,
    processingMetadata: {
      caseStatus: caseFile.status || 'unknown',
      intakeStatus: caseFile.intakeFormData?.status || 'unknown',
      documentsStatus: caseFile.caseDocumentsAnalysis?.status || 'unknown'
    }
  }
}];

// Format Email Response - Get case info from Prepare Email Prompt node
const emailContent = $input.first().json.message.content;

// Get the case info from the Prepare Email Prompt node (not current input)
const prepareEmailData = $items("Prepare Email Prompt")[0]?.json || {};
const clientName = prepareEmailData.clientName || "Client";
const attorneyName = prepareEmailData.attorneyName || "Attorney";
const caseReference = prepareEmailData.caseReference || "CASE-UNKNOWN";

// Get case file for additional metadata, guarding against missing values
const mergeValidatorData = $items("Merge Validator")[0]?.json || {};
const caseFile = mergeValidatorData.validatedUnifiedCaseFile || {};
const caseId = caseFile.caseId || "UNKNOWN_CASE_ID";

// Clean up the email content
let emailBody = emailContent.replace(/^```\\s*|```\\s*$/g, '').trim();

// Extract subject if present
let subject = `Legal Analysis Findings - ${caseReference}`;
const subjectMatch = emailBody.match(/Subject:\\s*(.+)/i);
if (subjectMatch) {
  subject = subjectMatch[1].trim();
  emailBody = emailBody.replace(/Subject:\\s*.+\\n?/i, '').trim();
}

// Create email file content with ACTUAL values
const currentDate = new Date();
const attorneyEmail = attorneyName.toLowerCase().replace(/[^a-z]/g, '') + '@brflorida.com';
const clientEmail = clientName.toLowerCase().replace(/[^a-z]/g, '') + '@client.com';

const emlContent = `From: ${attorneyName} <${attorneyEmail}>\nTo: ${clientName} <${clientEmail}>\nSubject: ${subject}\nDate: ${currentDate.toUTCString()}\nMIME-Version: 1.0\nContent-Type: text/plain; charset=utf-8\n\n${emailBody}\n\n---\nGenerated by Legal Document Analysis Portal\nCase ID: ${caseId}\nProcessed: ${currentDate.toISOString()}`;

// Create downloadable files
const emlBase64 = Buffer.from(emlContent, 'utf8').toString('base64');
const txtBase64 = Buffer.from(emailBody, 'utf8').toString('base64');

const cleanCaseRef = caseReference.replace(/[^a-zA-Z0-9]/g, '_');
const dateStr = currentDate.toISOString().split('T')[0];

return [{
  json: {
    status: "success",
    message: `✅ Legal Analysis Complete! Generated findings email for ${clientName}.`,
    documentsProcessed: 2,
    downloadLinks: {
      findingsLetter: `data:message/rfc822;base64,${emlBase64}`,
      caseAnalysis: `data:text/plain;base64,${txtBase64}`,
      executiveSummary: `data:text/plain;base64,${txtBase64}`
    },
    emailDetails: {
      subject: subject,
      from: `${attorneyName} <${attorneyEmail}>`,
      to: `${clientName} <${clientEmail}>`,
      emlFileName: `Findings_${cleanCaseRef}_${dateStr}.eml`
    },
    caseInfo: {
      caseId: caseId,
      clientName: clientName,
      attorneyName: attorneyName,
      caseReference: caseReference
    },
    analysisComplete: true,
    readyForDownload: true
  }
}];

// Final Response Formatter
// Ensures clean JSON response for frontend

const responseData = $input.first().json;

// Return the data in the exact format needed for the webhook response
return [{ json: responseData }];

// Generate debug package with workflow data for UI visibility
const debugPackage = {
  timestamp: new Date().toISOString(),
  workflow: '2_ai_processing',
  inputItemCount: $input.all().length,
  nodeExecutionData: $input.all(),
  executionInfo: {
    nodeId: 'Generate & Send Debug Package',
    processingTime: new Date().toISOString(),
    dataTypes: $input.all().map(item => ({
      hasJson: !!item.json,
      hasBinary: !!item.binary,
      jsonKeys: item.json ? Object.keys(item.json) : [],
      binaryKeys: item.binary ? Object.keys(item.binary) : []
    }))
  }
};

// Return both debug output (visible in Node Output → JSON) and pass-through data
return [
  // First output: Debug data (visible in UI)
  { 
    json: { 
      debug: debugPackage,
      message: 'Debug package generated - check Node Output → JSON tab'
    } 
  },
  // Remaining outputs: Pass through original data for workflow continuation
  ...$input.all()
];
